  hat("nxaviateur", c => vol("M-50,4 C-54,-58 -28,-74 0,-74 C28,-74 54,-58 50,4 C46,-8 44,-22 38,-28 Q0,-40 -38,-28 C-44,-22 -46,-8 -50,4Z", "#8a5a30", "") + two0(C(-16, -34, 10, "#bfe6ff", "#4a4558", 3)) + N("M-6,-34 H6", "#4a4558", 3) + N("M-26,-34 L-48,-30", "#4a4558", 3));
