  hat("nxlutin", c => vol("M-48,-22 C-48,-60 -20,-76 6,-78 C30,-80 58,-70 70,-40 C64,-44 56,-46 50,-44 C50,-34 49,-28 47,-22 Q0,-36 -48,-22Z", c, "") + P("M-50,-18 Q0,-36 50,-18 L48,-30 Q0,-46 -48,-30Z", "#fff", "#b5a8b5", 2) + C(70, -38, 6, "#ffd84d", "#a8761c", 1.4));
  hat("nxspeleo", c => vol(DOME, "#ffd84d", "") + P("M-48,-22 Q0,-38 48,-22 L46,-28 Q0,-44 -46,-28Z", "#a8801c") + R(-9, -64, 18, 12, 3, "#4a4558", "#15131b", 1.4) + C(0, -58, 4, "#fff6a5", "", 0) + P("M-6,-60 L-34,-110 H34 L6,-60Z", "#fff6c9", "", 0, 'opacity=".22"'));
  hat("nxtrain", c => vol("M-46,-22 C-48,-52 -30,-66 0,-66 C30,-66 48,-52 46,-22 Q0,-34 -46,-22Z", "#2f3566", "") + P("M-34,-24 Q0,-36 34,-24 Q46,-16 32,-12 Q0,-24 -32,-12 Q-46,-16 -34,-24Z", "#15131b") + band("#e5485a", -30) + C(0, -48, 5, "#ffd84d", "#a8761c", 1.2));
  hat("nxchantier", c => vol(DOME, c, "") + P("M-58,-22 Q0,-40 58,-22 L54,-14 Q0,-30 -54,-14Z", dk(c, .1), dk(c, .4), 2) + N("M0,-73 V-34", dk(c, .2), 4));
