  hat("nxvelo", c => vol(DOME, c, "") + N("M-30,-66 Q-10,-50 -4,-30 M0,-73 V-34 M30,-66 Q10,-50 4,-30", "#fff", 3.4, 'opacity=".7"') + two0(N("M-44,-24 Q-46,0 -30,22", "#4a4558", 2)));
  hat("nxsamourai", c => vol(DOME, "#2f2b3a", "") + P("M-62,-20 Q-50,-36 -44,-28 Q0,-42 44,-28 Q50,-36 62,-20 Q50,-14 0,-22 Q-50,-14 -62,-20Z", "#2f2b3a", "#15131b", 2) + P("M-16,-60 C-20,-88 -6,-92 0,-74 C6,-92 20,-88 16,-60Z", "#ffd84d", "#a8761c", 1.6));
