  CRN.nxlaurier = () => N("M-38,-26 Q0,-52 38,-26", "#7a8a3a", 3) + [-34, -24, -14, -4, 6, 16, 26].map((x, i) => `<path d="M${x},${-32 - (24 - Math.abs(x)) * .4} q4,-9 11,-8 q-2,8 -11,8Z" fill="${i % 2 ? "#8fb54a" : "#a8cf5a"}" stroke="#4f6b24" stroke-width="1"/>`).join("");
