  CRN.nxdiademeR = c => N("M-38,-26 Q0,-52 38,-26", "#c9d3e2", 3) + [-24, 0, 24].map((x, i) => gem(x, -38 - (i === 1 ? 8 : 0), i === 1 ? 7 : 5, c)).join("");
  CRN.nxlunettesN = c => two0(C(-17, 3, 13, "none", c, 3.4)) + N("M-4,1 Q0,-2 4,1", c, 3);

  // ======================== EFFETS ET SUR-TENUES ========================
  FXR.bulle = (st, c, txt) => { const [x, y, k] = st < 2 ? [156, 26, 1] : [100 + 58 * c.hs, c.hy - 40 * c.hs, .8 + .4 * c.hs]; const t = (txt || "?").replace(/_/g, " "); return { f: G(`translate(${x} ${y}) scale(${k})`, P("M-28,-14 H24 Q30,-14 30,-8 V6 Q30,12 24,12 H-6 L-16,22 L-14,12 H-28 Q-34,12 -34,6 V-8 Q-34,-14 -28,-14Z", "#fff", "#5a566b", 1.8) + TXT(-2, 4, t, t.length > 6 ? 8 : 11, "#5a3a8f")) }; };
  FXR.zz = st => ({ f: `<g class="float">${TXT(158, 40, "z", 22, "#8f9fe0")}${TXT(172, 22, "z", 16, "#b5c0f0")}</g>` });
  FXR.meche = (st, c, col) => st < 2 ? {} : { f: N(`M${100 - 16 * c.hs},${c.hy - 44 * c.hs} Q${100 - 30 * c.hs},${c.hy - 26 * c.hs} ${100 - 33 * c.hs},${c.hy + 4 * c.hs}`, "#" + col, 7 * c.hs) };
  FXR.peinture = (st, c) => st < 2 ? { f: [[56, 120, "#e5485a"], [140, 150, "#5fa8f0"], [96, 172, "#ffd84d"]].map(([x, y, k]) => C(x, y, 5, k, "", 0)).join("") } : { f: [c.hL, c.hR].map(([x, y], i) => C(x + 2, y + 2, 3.4 * K.KU[st], ["#e5485a", "#5fa8f0"][i], "", 0)).join("") + C(100 + 16 * c.hs, c.hy + 14 * c.hs, 4 * c.hs, "#7fc98a", "", 0) + E(100, 191, 30, 4, "#ffd84d", "", 0, 'opacity=".7"') };
  FXR.eclair = (st, c) => st < 2 ? {} : { f: P(`M${100 + 40 * c.hs},${c.hy - 50 * c.hs} l-8,14 h7 l-5,14 l13,-18 h-7 l5,-10Z`, "#ffd84d", "#a8761c", 1.2) };
  FXR.bulles2 = st => ({ f: `<g class="float">${[[30, 60, 7], [170, 44, 9], [24, 120, 5], [178, 110, 6]].map(([x, y, r]) => C(x, y, r * K.KU[st], "#e5f6ff", "#8fc9ec", 1.4) + C(x - r * .3, y - r * .3, r * .25, "#fff", "", 0)).join("")}</g>` });
  FXR.flammes = st => ({ b: [[40, 190], [160, 190]].map(([x, y]) => P(`M${x - 8},${y} C${x - 12},${y - 14} ${x - 2},${y - 18} ${x},${y - 30} C${x + 2},${y - 18} ${x + 12},${y - 14} ${x + 8},${y}Z`, "#ff8f3c", "#d9501c", 1.4)).join("") });
  FXR.larmes = (st, c) => ({});
  FXR.feuilles = st => ({ f: `<g class="float">${[[26, 50, "#f5a04c"], [172, 64, "#e5485a"], [30, 130, "#ffd84d"], [176, 140, "#7fc46c"]].map(([x, y, k], i) => `<path d="M${x},${y} q6,-8 12,0 q-6,8 -12,0Z" fill="${k}" transform="rotate(${i * 40} ${x} ${y})"/>`).join("")}</g>` });
  FXR.ondes = (st, c) => st < 2 ? {} : { f: [1, 2, 3].map(i => N(`M${c.hR[0] + 8 + i * 6},${c.hR[1] - 20 - i * 4} q${6 + i * 2},${8 + i * 2} 0,${18 + i * 4}`, "#8fc4f0", 2, 'opacity=".7"')).join("") };
  // sur-tenues en plus : collier de fleurs, toge, armure, sacoche, nœud papillon, cravate, médaille, plastron, gilet de sauvetage
  const u = c => c.w / 24;
  COATX.lei = (o, c) => [-.8, -.55, -.3, 0, .3, .55, .8].map((k, i) => fl(100 + k * c.w, c.sy + 4 + (1 - Math.abs(k)) * 10 * u(c), 3.4 * u(c) + 1, ["#ff6f9c", "#ffd84d", "#fff", "#ff8f5c"][i % 4])).join("");
  COATX.toge = (o, c) => { const { w, sy, hip } = c; return vol(`M${100 - w * .9},${sy + 4} L${100 + w * .3},${hip + 2} L${100 + w * .95},${hip} L${100 - w * .2},${sy}Z`, o.col, o.mo || "", 1.6) + C(100 - w * .55, sy + 6, 3 * u(c), "#ffd84d", "#a8761c", 1); };
  COATX.armure = (o, c) => { const { w, sy, hip, mid } = c; return vol(`M${100 - w * .9},${sy + 6} Q100,${sy} ${100 + w * .9},${sy + 6} L${100 + w * .8},${mid + 8} Q100,${hip + 2} ${100 - w * .8},${mid + 8}Z`, "#c9d3e2", "", 1.8) + N(`M100,${sy + 4} V${hip - 2}`, "#8a94a8", 1.4) + P(starD(100, mid - 2, 6 * u(c)), o.col || "#ffd84d"); };
  COATX.sacoche = (o, c) => { const { w, sy, hip, mid } = c; return N(`M${100 - w * .7},${sy} L${100 + w * .9},${hip - 4}`, dk(o.col, .4), 4 * u(c) + 1) + N(`M${100 - w * .7},${sy} L${100 + w * .9},${hip - 4}`, o.col, 2.6 * u(c) + .5) + R(100 + w * .5, hip - 10, w * .8, w * .6, 3, o.col, dk(o.col, .4), 1.4) + C(100 + w * .9, hip - 4, 1.6 * u(c), "#ffd84d", "", 0); };
  COATX.noeudpap = (o, c) => G(`translate(100 ${c.sy + 4 * u(c)}) scale(${u(c) * .9})`, P("M0,0 L-11,-6 L-11,6Z M0,0 L11,-6 L11,6Z", o.col, dk(o.col, .4), 1.4) + C(0, 0, 2.6, dk(o.col, .1)));
  COATX.cravate = (o, c) => G(`translate(100 ${c.sy + 2}) scale(${u(c)})`, P("M-3,0 H3 L2,4 L6,26 L0,32 L-6,26 L-2,4Z", o.col, dk(o.col, .4), 1.2) + (o.mo ? `<path d="M-3,0 H3 L2,4 L6,26 L0,32 L-6,26 L-2,4Z" fill="url(#rg${o.mo})"/>` : ""));
